INSERT INTO system_vocabulary_words (id, set_id, topic_id, part_id, word, ipa, cefr, part_of_speech, meaning_vi, definition_en, example_en, example_vi, example_toeic, audio_us, audio_uk, image_url, synonyms, antonyms, phrases, confusables, word_family, audio_voices, note_vi, toeic_topic, difficulty_level, order_index) VALUES
('eb47c238-a047-5bd5-9d1f-1206d6e355e5', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '02712dbd-9ebd-5930-995f-55a60f39eccc', '7953d083-5526-5a09-842f-8be9311d4733', 'engage', '/ɪnˈɡeɪdʒ/', 'B2', 'verb', 'Thu hút hoặc tham gia vào một hoạt động, cuộc trò chuyện.', 'to participate or become involved in an activity, conversation, or formal arrangement.', 'It\'s important to engage with the local community to understand their needs.', 'Điều quan trọng là phải tham gia với cộng đồng địa phương để hiểu nhu cầu của họ.', '{\"en\": \"Employees are encouraged to engage actively in discussion during the annual corporate workshop.\", \"vi\": \"Nhân viên được khuyến khích tích cực tham gia thảo luận trong buổi hội thảo doanh nghiệp hàng năm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/engage-ljspeech-7d7289b5.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/engage-cori-7d7289b5.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/engage-4e0936e4.webp', '[\"participate\", \"involve\", \"join\"]', '[\"disengage\", \"ignore\"]', '[{\"phrase\": \"engage in discussion\", \"meaning\": \"tham gia thảo luận\"}, {\"phrase\": \"engage with customers\", \"meaning\": \"tương tác với khách hàng\"}, {\"phrase\": \"engage a consultant\", \"meaning\": \"thuê cố vấn\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"engagement\"}, {\"pos\": \"adjective\", \"word\": \"engaging\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/engage-cori-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-aru0-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-aru5-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-aru6-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-aru10-7d7289b5.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/engage-aru9-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-aru3-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-aru7-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-aru8-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-aru2-7d7289b5.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/engage-ljspeech-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-lt408-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-lt138-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-lt624-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-lt396-7d7289b5.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/engage-lt498-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-lt132-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-lt288-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-lt42-7d7289b5.mp3\", \"/storage/v1/object/public/pronunciation/v2/engage-lt90-7d7289b5.mp3\"]}}', 'Engage đi với \'in\' nghĩa là tham gia; đi với \'with\' nghĩa là tương tác.', 'hr', 1, 0),
('32cbabc3-4d41-5ee5-84db-f14fb89f591e', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '02712dbd-9ebd-5930-995f-55a60f39eccc', '7953d083-5526-5a09-842f-8be9311d4733', 'drone', 'UK: /drəʊn/ | US: /droʊn/', 'B2', 'noun', 'máy bay không người lái', 'an aircraft controlled remotely without a pilot on board to capture images or transport items.', 'The drone captured stunning aerial footage of the landscape.', 'Chiếc máy bay không người lái đã ghi lại những cảnh quay tuyệt đẹp từ trên cao của phong cảnh.', '{\"en\": \"The real estate agency used a drone to capture aerial footage of the commercial property.\", \"vi\": \"Công ty bất động sản đã sử dụng máy bay không người lái để quay phim từ trên cao khu bất động sản thương mại.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/drone-ljspeech-1430fd26.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/drone-cori-1430fd26.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/drone-94c026f0.webp', '[\"unmanned aerial vehicle\", \"UAV\"]', NULL, '[{\"phrase\": \"drone delivery\", \"meaning\": \"giao hàng bằng máy bay không người lái\"}, {\"phrase\": \"operate a drone\", \"meaning\": \"vận hành máy bay không người lái\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/drone-cori-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-aru0-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-aru5-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-aru6-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-aru10-1430fd26.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/drone-aru9-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-aru3-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-aru7-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-aru8-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-aru2-1430fd26.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/drone-ljspeech-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-lt408-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-lt138-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-lt624-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-lt396-1430fd26.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/drone-lt498-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-lt132-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-lt288-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-lt42-1430fd26.mp3\", \"/storage/v1/object/public/pronunciation/v2/drone-lt90-1430fd26.mp3\"]}}', 'Trong bối cảnh doanh nghiệp hiện đại, \'drone\' thường được dùng trong quay chụp quảng cáo bất động sản, kiểm tra công trình hoặc giao hàng tự động.', 'technology', 1, 1),
('8c82027f-0644-5b21-8736-01d8918fcde3', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '02712dbd-9ebd-5930-995f-55a60f39eccc', '7953d083-5526-5a09-842f-8be9311d4733', 'description', '/dɪˈskrɪpʃn/', 'B1', 'noun', 'Sự diễn tả chi tiết về đặc điểm của một người, vật hoặc sự kiện.', 'a statement that tells you what something or someone is like.', 'The witness gave a clear description of the suspect to the police.', 'Nhân chứng đã đưa ra một mô tả rõ ràng về nghi phạm cho cảnh sát.', '{\"en\": \"The job description includes responsibilities such as managing client accounts and preparing weekly reports.\", \"vi\": \"Mô tả công việc bao gồm các trách nhiệm như quản lý tài khoản khách hàng và chuẩn bị báo cáo hàng tuần.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/description-ljspeech-cb329146.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/description-cori-cb329146.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/description-976b7eee.webp', '[\"explanation\", \"account\"]', NULL, '[{\"phrase\": \"job description\", \"meaning\": \"mô tả công việc\"}, {\"phrase\": \"detailed description\", \"meaning\": \"mô tả chi tiết\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"describe\"}, {\"pos\": \"adjective\", \"word\": \"descriptive\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/description-cori-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-aru0-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-aru5-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-aru6-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-aru10-cb329146.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/description-aru9-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-aru3-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-aru7-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-aru8-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-aru2-cb329146.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/description-ljspeech-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-lt408-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-lt138-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-lt624-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-lt396-cb329146.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/description-lt498-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-lt132-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-lt288-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-lt42-cb329146.mp3\", \"/storage/v1/object/public/pronunciation/v2/description-lt90-cb329146.mp3\"]}}', 'Cụm \'job description\' là từ khóa cực kỳ phổ biến trong chủ đề tuyển dụng.', 'hr', 1, 2),
('5c35e1f8-890f-58dd-a65c-bffeef568e94', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '02712dbd-9ebd-5930-995f-55a60f39eccc', '7953d083-5526-5a09-842f-8be9311d4733', 'agree', '/əˈɡriː/', 'A1', 'verb', 'Có cùng quan điểm hoặc chấp thuận một đề xuất.', 'to have the same opinion as someone else or accept a suggestion.', 'We all agree that the new plan is the best option.', 'Tất cả chúng tôi đều đồng ý rằng kế hoạch mới là lựa chọn tốt nhất.', '{\"en\": \"The board members did not agree on the budget proposal during the morning session.\", \"vi\": \"Các thành viên hội đồng không đồng ý với đề xuất ngân sách trong phiên họp sáng nay.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/agree-ljspeech-c9600527.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/agree-cori-c9600527.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/agree-de858d5b.webp', '[\"consent\", \"concur\"]', '[\"disagree\", \"oppose\"]', '[{\"phrase\": \"agree with\", \"meaning\": \"đồng ý với\"}, {\"phrase\": \"agree on\", \"meaning\": \"thống nhất về\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"agreement\"}, {\"pos\": \"adjective\", \"word\": \"agreeable\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/agree-cori-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-aru0-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-aru5-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-aru6-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-aru10-c9600527.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/agree-aru9-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-aru3-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-aru7-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-aru8-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-aru2-c9600527.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/agree-ljspeech-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-lt408-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-lt138-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-lt624-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-lt396-c9600527.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/agree-lt498-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-lt132-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-lt288-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-lt42-c9600527.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree-lt90-c9600527.mp3\"]}}', 'Chú ý giới từ: \'agree with\' (người), \'agree on/upon\' (vấn đề).', 'business', 1, 3),
('2324acc3-1a87-5a31-ba99-6b8f8492f673', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '02712dbd-9ebd-5930-995f-55a60f39eccc', '7953d083-5526-5a09-842f-8be9311d4733', 'disruption', '/dɪsˈrʌpʃn/', 'B2', 'noun', 'Sự gián đoạn, làm ngừng trệ hoạt động bình thường.', 'a situation in which an activity or system is prevented from continuing normally.', 'The heavy snow caused significant disruption to public transport services.', 'Trận tuyết rơi dày đã gây ra sự gián đoạn đáng kể cho các dịch vụ giao thông công cộng.', '{\"en\": \"Severe weather conditions caused significant disruption to flight schedules at the airport.\", \"vi\": \"Thời tiết khắc nghiệt đã gây ra sự gián đoạn đáng kể đối với lịch trình chuyến bay tại sân bay.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/disruption-ljspeech-2eb7fdce.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/disruption-cori-2eb7fdce.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/disruption-9a761cd8.webp', '[\"disturbance\", \"interruption\"]', '[\"continuation\", \"stability\"]', '[{\"phrase\": \"cause disruption\", \"meaning\": \"gây ra sự gián đoạn\"}, {\"phrase\": \"major disruption\", \"meaning\": \"sự gián đoạn lớn\"}]', '[{\"word\": \"eruption\", \"note_vi\": \"sự phun trào của núi lửa\"}]', '[{\"pos\": \"verb\", \"word\": \"disrupt\"}, {\"pos\": \"adjective\", \"word\": \"disruptive\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/disruption-cori-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-aru0-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-aru5-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-aru6-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-aru10-2eb7fdce.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/disruption-aru9-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-aru3-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-aru7-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-aru8-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-aru2-2eb7fdce.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/disruption-ljspeech-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-lt408-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-lt138-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-lt624-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-lt396-2eb7fdce.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/disruption-lt498-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-lt132-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-lt288-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-lt42-2eb7fdce.mp3\", \"/storage/v1/object/public/pronunciation/v2/disruption-lt90-2eb7fdce.mp3\"]}}', 'Thường đi với động từ \'cause\' hoặc \'experience\' trong các bài đọc thông báo giao thông.', 'travel', 1, 4),
('9764720b-c6c9-524d-bf0b-2b1e12e13547', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '02712dbd-9ebd-5930-995f-55a60f39eccc', '7953d083-5526-5a09-842f-8be9311d4733', 'conduct', '/kənˈdʌkt/', 'B2', 'verb', 'Thực hiện, tổ chức (một hoạt động, nghiên cứu).', 'to organize and carry out a particular activity, plan, or research.', 'The university will conduct a survey to gather student feedback.', 'Trường đại học sẽ tiến hành một cuộc khảo sát để thu thập phản hồi của sinh viên.', '{\"en\": \"The manager will conduct a thorough performance review for all new employees tomorrow.\", \"vi\": \"Trưởng phòng sẽ tiến hành đánh giá hiệu suất toàn diện cho tất cả nhân viên mới vào ngày mai.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/conduct-ljspeech-1f005da3.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/conduct-cori-1f005da3.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/conduct-c11cb67d.webp', '[\"perform\", \"execute\", \"implement\"]', NULL, '[{\"phrase\": \"conduct a survey\", \"meaning\": \"tiến hành một cuộc khảo sát\"}, {\"phrase\": \"conduct an interview\", \"meaning\": \"thực hiện một cuộc phỏng vấn\"}, {\"phrase\": \"conduct research\", \"meaning\": \"tiến hành nghiên cứu\"}]', '[{\"word\": \"conduce\", \"note_vi\": \"conduce (dẫn đến) là động từ hiếm gặp, khác với conduct.\"}]', '[{\"pos\": \"noun\", \"word\": \"conduct\"}, {\"pos\": \"noun\", \"word\": \"conductor\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/conduct-cori-1f005da3.mp3\", \"/storage/v1/object/public/pronunciation/v2/conduct-aru0-1f005da3.mp3\", \"/storage/v1/object/public/pronunciation/v2/conduct-aru5-1f005da3.mp3\", \"/storage/v1/object/public/pronunciation/v2/conduct-aru6-1f005da3.mp3\", \"/storage/v1/object/public/pronunciation/v2/conduct-aru10-1f005da3.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/conduct-aru9-1f005da3.mp3\", \"/storage/v1/object/public/pronunciation/v2/conduct-aru3-1f005da3.mp3\", \"/st