('7eb3192c-c2d8-5021-9311-5b88dd2b59e9', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '25c1fc62-3306-50b4-bb28-30658b2239d6', '0dedb205-6964-5ac0-88a0-4f4976c1f96b', 'announcement', '/əˈnaʊnsmənt/', 'B1', 'noun', 'Lời thông báo hoặc công bố chính thức.', 'a public or official statement that gives people information about something.', 'Employees gathered in the main hall to hear the official announcement regarding salary increases.', 'Nhân viên đã tập hợp tại hội trường chính để nghe thông báo chính thức liên quan đến việc tăng lương.', '{\"en\": \"The CEO made an important announcement regarding the upcoming merger during the meeting.\", \"vi\": \"Giám đốc điều hành đã đưa ra một thông báo quan trọng về vụ sáp nhập sắp tới trong cuộc họp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/announcement-ljspeech-bd633590.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/announcement-cori-bd633590.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/announcement-9e0ad1c8.webp', '[\"statement\", \"declaration\", \"notification\"]', NULL, '[{\"phrase\": \"make an announcement\", \"meaning\": \"đưa ra thông báo\"}, {\"phrase\": \"official announcement\", \"meaning\": \"thông báo chính thức\"}, {\"phrase\": \"public announcement\", \"meaning\": \"thông báo công khai\"}]', '[{\"word\": \"advertisement\", \"note_vi\": \"advertisement là quảng cáo thương mại để bán hàng\"}]', '[{\"pos\": \"verb\", \"word\": \"announce\"}, {\"pos\": \"noun\", \"word\": \"announcer\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/announcement-cori-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru0-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru5-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru6-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru10-bd633590.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/announce