('640d8f1f-7ad4-5205-86ca-a191d74261dd', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '5e220f5c-df25-5169-8a72-80b28689b8fd', '1c88527e-4f24-5006-bbdd-418f073a995d', 'temporarily', 'UK: /ˈtɛmpərəli/ | US: /ˈtɛmpərɛrəli/', 'B2', 'adverb', 'tạm thời', 'for a limited period of time rather than permanently.', 'The office will be temporarily closed for renovations.', 'Văn phòng sẽ tạm thời đóng cửa để cải tạo.', '{\"en\": \"The online payment gateway is temporarily unavailable due to scheduled system maintenance.\", \"vi\": \"Cổng thanh toán trực tuyến tạm thời không khả dụng do bảo trì hệ thống theo kế hoạch.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/temporarily-ljspeech-fa03a142.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/temporarily-cori-fa03a142.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/temporarily-37569bad.webp', '[\"provisionally\", \"momentarily\"]', '[\"permanently\"]', '[{\"phrase\": \"temporarily closed\", \"meaning\": \"tạm thời đóng cửa\"}, {\"phrase\": \"temporarily suspended\", \"meaning\": \"tạm thời bị đình chỉ/hoãn\"}, {\"phrase\": \"temporarily out of stock\", \"meaning\": \"tạm thời hết hàng\"}]', '[{\"word\": \"permanently\", \"note_vi\": \"vĩnh viễn, lâu dài (từ trái nghĩa)\"}]', '[{\"pos\": \"adjective\", \"word\": \"temporary\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/temporarily-cori-fa03a142.mp3\", \"/storage/v1/object/public/pronunciation/v2/temporarily-aru0-fa03a142.mp3\", \"/storage/v1/object/public/pronunciation/v2/temporarily-aru5-fa03a142.mp3\", \"/storage/v1/object/public/pronunciation/v2/temporarily-aru6-fa03a142.mp3\", \"/storage/v1/object/public/pronunciation/v2/temporarily-aru10-fa03a142.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/temporarily-aru9-fa03a142.mp3\", \"/storage/v1/object/public/pronunciation/v2/temporarily-aru3-fa03a142.mp3\", \"/storage/v1/object/public/pronunciation/v2/temporarily-aru7-fa03a142.mp3\", \"/storage/v