('8c24e128-3b2e-51c5-8185-e12576e0e430', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '624ecff7-f3d9-5206-9f52-21bce5c1f362', 'e593b3be-7530-5900-af5c-0dd7fda48d34', 'agreement', '/əˈɡriːmənt/', 'B1', 'noun', 'một sự đồng ý hoặc hợp đồng chính thức giữa các bên.', 'a decision or arrangement that two or more people or groups make together.', 'The two countries signed a peace agreement after years of conflict.', 'Hai nước đã ký một thỏa thuận hòa bình sau nhiều năm xung đột.', '{\"en\": \"Both companies signed a formal agreement to collaborate on the new software project.\", \"vi\": \"Cả hai công ty đã ký một thỏa thuận chính thức để hợp tác trong dự án phần mềm mới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/agreement-ljspeech-c0e57121.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/agreement-cori-c0e57121.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/agreement-d5eb901d.webp', '[\"contract\", \"treaty\", \"deal\"]', '[\"disagreement\", \"dispute\"]', '[{\"phrase\": \"reach an agreement\", \"meaning\": \"đạt được thỏa thuận\"}, {\"phrase\": \"sign an agreement\", \"meaning\": \"ký kết thỏa thuận\"}]', '[{\"word\": \"contract\", \"note_vi\": \"contract là hợp đồng có tính pháp lý ràng buộc chặt chẽ hơn agreement.\"}]', '[{\"pos\": \"verb\", \"word\": \"agree\"}, {\"pos\": \"adjective\", \"word\": \"agreeable\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/agreement-cori-c0e57121.mp3\", \"/storage/v1/object/public/pronunciation/v2/agreement-aru0-c0e57121.mp3\", \"/storage/v1/object/public/pronunciation/v2/agreement-aru5-c0e57121.mp3\", \"/storage/v1/object/public/pronunciation/v2/agreement-aru6-c0e57121.mp3\", \"/storage/v1/object/public/pronunciation/v2/agreement-aru10-c0e57121.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/agreement-aru9-c0e57121.mp3\", \"/storage/v1/object/public/pronunciation/v2/agreement-aru3-c0e57121.mp3\", \"/storage/v1/object/public/pronunciation/v2/agree