('1d891396-6e27-5ce7-9c45-c417bd7799a3', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '64271236-20dc-5726-923f-58c2cbb5cbd5', '83f15ee5-93ad-5d22-b90e-892892c497e5', 'specialize', '/ˈspeʃəlaɪz/', 'B1', 'verb', 'Tập trung phát triển một lĩnh vực cụ thể.', 'to spend most of your time studying or working on one subject.', 'This hospital specializes in heart surgery.', 'Bệnh viện này chuyên về phẫu thuật tim.', '{\"en\": \"Our law firm specializes in intellectual property rights and corporate contracts.\", \"vi\": \"Văn phòng luật của chúng tôi chuyên về quyền sở hữu trí tuệ và hợp đồng doanh nghiệp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/specialize-ljspeech-ab7323ab.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/specialize-cori-ab7323ab.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/specialize-72af0bc8.webp', '[\"focus on\", \"concentrate on\"]', '[\"generalize\"]', '[{\"phrase\": \"specialize in\", \"meaning\": \"chuyên về lĩnh vực gì\"}]', '[{\"word\": \"special\", \"note_vi\": \"tính từ đặc biệt, specialize là động từ chuyên về\"}]', '[{\"pos\": \"adjective\", \"word\": \"special\"}, {\"pos\": \"noun\", \"word\": \"specialist\"}, {\"pos\": \"noun\", \"word\": \"specialization\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/specialize-cori-ab7323ab.mp3\", \"/storage/v1/object/public/pronunciation/v2/specialize-aru0-ab7323ab.mp3\", \"/storage/v1/object/public/pronunciation/v2/specialize-aru5-ab7323ab.mp3\", \"/storage/v1/object/public/pronunciation/v2/specialize-aru6-ab7323ab.mp3\", \"/storage/v1/object/public/pronunciation/v2/specialize-aru10-ab7323ab.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/specialize-aru9-ab7323ab.mp3\", \"/storage/v1/object/public/pronunciation/v2/specialize-aru3-ab7323ab.mp3\", \"/storage/v1/object/public/pronunciation/v2/specialize-aru7-ab7323ab.mp3\", \"/storage/v1/object/public/pronunciation/v2/specialize-aru8-ab7323ab.mp3\", \"/storage/v1/obj