('f6b311ce-0636-5fd2-b256-6c8b2497f25f', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '64271236-20dc-5726-923f-58c2cbb5cbd5', '83f15ee5-93ad-5d22-b90e-892892c497e5', 'disperse', '/dɪˈspɜːs/', 'C1', 'verb', 'Lan rộng hoặc làm tản ra nhiều hướng.', 'to spread across or move away over a large area.', 'Security personnel asked the visitors to disperse calmly from the main lobby.', 'Nhân viên an ninh đã yêu cầu khách tham quan giải tán một cách trật tự khỏi sảnh chính.', '{\"en\": \"The marketing team decided to disperse the promotional flyers across several busy shopping centers.\", \"vi\": \"Đội ngũ tiếp thị đã quyết định phân tán các tờ rơi quảng cáo khắp một số trung tâm mua sắm sầm uất.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/disperse-ljspeech-44963712.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/disperse-cori-44963712.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/disperse-e5344666.webp', '[\"scatter\", \"distribute\", \"spread\"]', '[\"gather\", \"collect\", \"assemble\"]', '[{\"phrase\": \"disperse a crowd\", \"meaning\": \"giải tán đám đông\"}, {\"phrase\": \"disperse seeds\", \"meaning\": \"phân tán hạt giống\"}]', '[{\"word\": \"dispense\", \"note_vi\": \"dispense là phân phát hoặc cung cấp, disperse là làm cho tản ra.\"}]', '[{\"pos\": \"noun\", \"word\": \"dispersion\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/disperse-cori-44963712.mp3\", \"/storage/v1/object/public/pronunciation/v2/disperse-aru0-44963712.mp3\", \"/storage/v1/object/public/pronunciation/v2/disperse-aru5-44963712.mp3\", \"/storage/v1/object/public/pronunciation/v2/disperse-aru6-44963712.mp3\", \"/storage/v1/object/public/pronunciation/v2/disperse-aru10-44963712.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/disperse-aru9-44963712.mp3\", \"/storage/v1/object/public/pronunciation/v2/disperse-aru3-44963712.mp3\", \"/storage/v1/object/public/pronunciation/v2/disperse-aru7-44963712.mp3\", \"/stora