('cb76e2e2-b187-5855-a043-7b98a9709536', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '75ac6c56-61b5-5fc0-9a48-24e3a6421aa1', '41f3af2c-5d90-5175-ae3d-499b2c511716', 'draw', '/drɔː/', 'A1', 'verb', 'Vẽ một hình hoặc bức tranh.', 'To produce an image or diagram by creating marks on a surface with instruments.', 'My little sister loves to draw animals in her notebook.', 'Em gái tôi rất thích vẽ động vật vào sổ của mình.', '{\"en\": \"The architect will draw a new floor plan for the upcoming office renovation project.\", \"vi\": \"Kiến trúc sư sẽ vẽ một sơ đồ tầng mới cho dự án cải tạo văn phòng sắp tới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/draw-ljspeech-76a4e12c.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/draw-cori-76a4e12c.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/draw-d2fbe1dd.webp', '[\"sketch\", \"illustrate\"]', '[\"erase\"]', '[{\"phrase\": \"draw a map\", \"meaning\": \"vẽ bản đồ\"}, {\"phrase\": \"draw a diagram\", \"meaning\": \"vẽ biểu đồ\"}]', '[{\"word\": \"draft\", \"note_vi\": \"draft là phác thảo, viết nháp, không hẳn là vẽ hình ảnh.\"}]', '[{\"pos\": \"noun\", \"word\": \"drawing\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/draw-cori-76a4e12c.mp3\", \"/storage/v1/object/public/pronunciation/v2/draw-aru0-76a4e12c.mp3\", \"/storage/v1/object/public/pronunciation/v2/draw-aru5-76a4e12c.mp3\", \"/storage/v1/object/public/pronunciation/v2/draw-aru6-76a4e12c.mp3\", \"/storage/v1/object/public/pronunciation/v2/draw-aru10-76a4e12c.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/draw-aru9-76a4e12c.mp3\", \"/storage/v1/object/public/pronunciation/v2/draw-aru3-76a4e12c.mp3\", \"/storage/v1/object/public/pronunciation/v2/draw-aru7-76a4e12c.mp3\", \"/storage/v1/object/public/pronunciation/v2/draw-aru8-76a4e12c.mp3\", \"/storage/v1/object/public/pronunciation/v2/draw-aru2-76a4e12c.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/draw-ljsp