('33152350-4c95-5f39-8094-2877aece72e7', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '8299c8cb-0512-5f37-8a9b-6e70c0a062ee', '0b4b5175-430b-5e88-a149-ff00b8859c06', 'domestic', 'UK: /dəˈmɛstɪk/ | US: /dəˈmɛstɪk/', 'B2', 'adjective', 'trong nước', 'relating to or happening inside a particular country rather than internationally.', 'Our company focuses on both domestic and international markets.', 'Công ty chúng tôi tập trung vào cả thị trường trong nước và quốc tế.', '{\"en\": \"Due to high demand, the airline is expanding its domestic flight routes.\", \"vi\": \"Do nhu cầu cao, hãng hàng không đang mở rộng các tuyến bay nội địa.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/domestic-ljspeech-9ca881d7.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/domestic-cori-9ca881d7.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/domestic-0c8cb2e5.webp', '[\"internal\", \"national\", \"local\", \"home\"]', '[\"international\", \"foreign\", \"overseas\"]', '[{\"phrase\": \"domestic flight\", \"meaning\": \"chuyến bay nội địa\"}, {\"phrase\": \"domestic market\", \"meaning\": \"thị trường trong nước\"}, {\"phrase\": \"domestic sales\", \"meaning\": \"doanh số trong nước\"}]', NULL, '[{\"pos\": \"adverb\", \"word\": \"domestically\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/domestic-cori-9ca881d7.mp3\", \"/storage/v1/object/public/pronunciation/v2/domestic-aru0-9ca881d7.mp3\", \"/storage/v1/object/public/pronunciation/v2/domestic-aru5-9ca881d7.mp3\", \"/storage/v1/object/public/pronunciation/v2/domestic-aru6-9ca881d7.mp3\", \"/storage/v1/object/public/pronunciation/v2/domestic-aru10-9ca881d7.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/domestic-aru9-9ca881d7.mp3\", \"/storage/v1/object/public/pronunciation/v2/domestic-aru3-9ca881d7.mp3\", \"/storage/v1/object/public/pronunciation/v2/domestic-aru7-9ca881d7.mp3\", \"/storage/v1/object/public/pronunciation/v2/domestic-aru8-9ca881d7.mp3\", \"/