('ab78ee24-df95-51ca-b7a2-4f100cd85f64', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '8299c8cb-0512-5f37-8a9b-6e70c0a062ee', '0b4b5175-430b-5e88-a149-ff00b8859c06', 'due date', 'UK: /ˈdjuː deɪt/ | US: /ˈduː deɪt/', 'B1', 'phrase', 'ngày đáo hạn, hạn chót', 'the specific day by which something must be completed, returned, or paid.', 'Please submit your report by the due date.', 'Vui lòng nộp báo cáo của bạn trước ngày đáo hạn.', '{\"en\": \"Clients will incur a late payment penalty if they miss the due date.\", \"vi\": \"Khách hàng sẽ bị tính phí phạt nộp chậm nếu họ bỏ lỡ ngày đáo hạn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/due-date-ljspeech-798792a2.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/due-date-cori-798792a2.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/due-date-75741577.webp', '[\"deadline\", \"target date\", \"expiration date\"]', NULL, '[{\"phrase\": \"extend the due date\", \"meaning\": \"gia hạn ngày hạn chót\"}, {\"phrase\": \"meet the due date\", \"meaning\": \"hoàn thành đúng hạn chót\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/due-date-cori-798792a2.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-date-aru0-798792a2.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-date-aru5-798792a2.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-date-aru6-798792a2.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-date-aru10-798792a2.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/due-date-aru9-798792a2.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-date-aru3-798792a2.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-date-aru7-798792a2.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-date-aru8-798792a2.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-date-aru2-798792a2.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/due-date-ljspeech-798792a2.mp3\", \"/storage/v1/object/pu