('fe0685e4-422a-57ee-b326-c154b3112a31', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '83ed673a-d7c8-56fd-92ed-b47205f1629c', '9ca8d168-b494-5abe-b065-71e7d0b04a57', 'suite', 'UK: /ˈsuːtɪd/ | US: /ˈsuːtɪd/', 'B2', 'adjective', 'phù hợp', 'having the necessary qualities or skills to fit a particular role or purpose', 'This candidate is well suited for the management position.', 'Ứng viên này rất phù hợp cho vị trí quản lý.', '{\"en\": \"The executive board agreed that Ms. Taylor is well suite for the lead editor position.\", \"vi\": \"Hội đồng quản trị đồng ý rằng cô Taylor rất phù hợp cho vị trí biên tập viên chính.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/suite-ljspeech-5cd55651.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/suite-cori-5cd55651.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/suite-b31ed21c.webp', '[\"suited\", \"qualified\", \"eligible\"]', '[\"unsuited\"]', '[{\"phrase\": \"well suite for\", \"meaning\": \"rất phù hợp với\"}, {\"phrase\": \"suite candidates\", \"meaning\": \"các ứng viên thích hợp\"}]', '[{\"word\": \"suite\", \"note_vi\": \"Danh từ \'suite\' phát âm là /swiːt/, chỉ dãy phòng khách sạn sang trọng hoặc một bộ phần mềm ứng dụng.\"}]', '[{\"pos\": \"verb\", \"word\": \"suit\"}, {\"pos\": \"noun\", \"word\": \"suitability\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/suite-cori-5cd55651.mp3\", \"/storage/v1/object/public/pronunciation/v2/suite-aru0-5cd55651.mp3\", \"/storage/v1/object/public/pronunciation/v2/suite-aru5-5cd55651.mp3\", \"/storage/v1/object/public/pronunciation/v2/suite-aru6-5cd55651.mp3\", \"/storage/v1/object/public/pronunciation/v2/suite-aru10-5cd55651.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/suite-aru9-5cd55651.mp3\", \"/storage/v1/object/public/pronunciation/v2/suite-aru3-5cd55651.mp3\", \"/storage/v1/object/public/pronunciation/v2/suite-aru7-5cd55651.mp3\", \"/storage/v1/object/public/pronunciation/v2/suite-aru8-5c