('596b9271-dc31-5f70-9802-6d81052773ec', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '8b87e05a-a2c4-59a1-bf2c-c275f2a65c86', '427aced2-a7ef-5adc-8430-3c35ec99abbb', 'recruit', '/rɪˈkruːt/', 'B2', 'verb', 'Tuyển chọn người mới vào làm việc hoặc tham gia tổ chức.', 'To enlist individuals to work for a company or participate in a specific activity.', 'The company plans to recruit more engineers next quarter.', 'Công ty dự định tuyển thêm kỹ sư vào quý tới.', '{\"en\": \"The human resources department is looking to recruit several experienced engineers for the new project.\", \"vi\": \"Bộ phận nhân sự đang tìm cách tuyển dụng một vài kỹ sư có kinh nghiệm cho dự án mới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/recruit-ljspeech-9332e450.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/recruit-cori-9332e450.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/recruit-907e838c.webp', '[\"hire\", \"employ\"]', '[\"dismiss\", \"fire\"]', '[{\"phrase\": \"recruit staff\", \"meaning\": \"tuyển nhân viên\"}, {\"phrase\": \"actively recruit\", \"meaning\": \"tích cực tuyển dụng\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"recruitment\"}, {\"pos\": \"noun\", \"word\": \"recruiter\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/recruit-cori-9332e450.mp3\", \"/storage/v1/object/public/pronunciation/v2/recruit-aru0-9332e450.mp3\", \"/storage/v1/object/public/pronunciation/v2/recruit-aru5-9332e450.mp3\", \"/storage/v1/object/public/pronunciation/v2/recruit-aru6-9332e450.mp3\", \"/storage/v1/object/public/pronunciation/v2/recruit-aru10-9332e450.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/recruit-aru9-9332e450.mp3\", \"/storage/v1/object/public/pronunciation/v2/recruit-aru3-9332e450.mp3\", \"/storage/v1/object/public/pronunciation/v2/recruit-aru7-9332e450.mp3\", \"/storage/v1/object/public/pronunciation/v2/recruit-aru8-9332e450.mp3\", \"/storage/v1/object/public/pronunciation/v2/recruit-aru2-9332e