('48b94622-d8b6-5c90-901a-503eef9c1827', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '8d4720c5-92f0-5b25-9d9a-cae2b63490f6', 'c378b129-9b54-5189-8e7a-f9eb48303f23', 'rehearse', '/rɪˈhɜːs/', 'B2', 'verb', 'luyện tập một buổi biểu diễn hoặc bài phát biểu.', 'to practice a play, a piece of music, or a speech before performing it in public.', 'The actors will rehearse the play several times before opening night.', 'Các diễn viên sẽ diễn tập vở kịch nhiều lần trước đêm công diễn.', '{\"en\": \"The team needs to rehearse the presentation before the client arrives for the meeting.\", \"vi\": \"Cả nhóm cần diễn tập bài thuyết trình trước khi khách hàng đến họp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/rehearse-ljspeech-894d8871.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/rehearse-cori-894d8871.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/rehearse-5acd5edb.webp', '[\"practice\", \"prepare\"]', NULL, '[{\"phrase\": \"rehearse a speech\", \"meaning\": \"diễn tập bài phát biểu\"}, {\"phrase\": \"rehearse a presentation\", \"meaning\": \"diễn tập bài thuyết trình\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"rehearsal\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/rehearse-cori-894d8871.mp3\", \"/storage/v1/object/public/pronunciation/v2/rehearse-aru0-894d8871.mp3\", \"/storage/v1/object/public/pronunciation/v2/rehearse-aru5-894d8871.mp3\", \"/storage/v1/object/public/pronunciation/v2/rehearse-aru6-894d8871.mp3\", \"/storage/v1/object/public/pronunciation/v2/rehearse-aru10-894d8871.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/rehearse-aru9-894d8871.mp3\", \"/storage/v1/object/public/pronunciation/v2/rehearse-aru3-894d8871.mp3\", \"/storage/v1/object/public/pronunciation/v2/rehearse-aru7-894d8871.mp3\", \"/storage/v1/object/public/pronunciation/v2/rehearse-aru8-894d8871.mp3\", \"/storage/v1/object/public/pronunciation/v2/rehearse-aru2-894d8871.mp3\"]}, \"us\": {\"nu\": [\"/stora