('45777a37-5a31-599a-9ca0-2d37bf2ba589', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', '8d4720c5-92f0-5b25-9d9a-cae2b63490f6', 'c378b129-9b54-5189-8e7a-f9eb48303f23', 'select', '/sɪˈlekt/', 'A2', 'verb', 'Chọn, lựa chọn cẩn thận.', 'to choose someone or something from a group of people or things.', 'Please select the best answer from the options provided.', 'Vui lòng chọn câu trả lời đúng nhất từ các lựa chọn đã cho.', '{\"en\": \"The committee will select the most qualified candidate for the senior management position.\", \"vi\": \"Ủy ban sẽ chọn ứng viên có trình độ phù hợp nhất cho vị trí quản lý cấp cao.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/select-ljspeech-81448fe2.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/select-cori-81448fe2.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/select-0ca79d48.webp', '[\"choose\", \"pick\", \"opt\"]', '[\"reject\", \"refuse\"]', '[{\"phrase\": \"select a candidate\", \"meaning\": \"chọn một ứng viên\"}, {\"phrase\": \"carefully select\", \"meaning\": \"lựa chọn cẩn thận\"}, {\"phrase\": \"select from\", \"meaning\": \"chọn từ\"}]', '[{\"word\": \"choose\", \"note_vi\": \"Choose thông dụng hơn, select mang tính trang trọng và kỹ lưỡng hơn.\"}]', '[{\"pos\": \"noun\", \"word\": \"selection\"}, {\"pos\": \"adjective\", \"word\": \"selective\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/select-cori-81448fe2.mp3\", \"/storage/v1/object/public/pronunciation/v2/select-aru0-81448fe2.mp3\", \"/storage/v1/object/public/pronunciation/v2/select-aru5-81448fe2.mp3\", \"/storage/v1/object/public/pronunciation/v2/select-aru6-81448fe2.mp3\", \"/storage/v1/object/public/pronunciation/v2/select-aru10-81448fe2.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/select-aru9-81448fe2.mp3\", \"/storage/v1/object/public/pronunciation/v2/select-aru3-81448fe2.mp3\", \"/storage/v1/object/public/pronunciation/v2/select-aru7-81448fe2.mp3\", \"/storage/v1/object/pub