INSERT INTO system_vocabulary_words (id, set_id, topic_id, part_id, word, ipa, cefr, part_of_speech, meaning_vi, definition_en, example_en, example_vi, example_toeic, audio_us, audio_uk, image_url, synonyms, antonyms, phrases, confusables, word_family, audio_voices, note_vi, toeic_topic, difficulty_level, order_index) VALUES
('51b7728f-38f4-5a03-b4ad-fdc81f1b940d', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', 'bd06fdb4-aaee-573a-88da-8be75b94f77f', '7d041f49-ed3c-576f-b4fb-1a623a43534d', 'pick up', '/pɪk ʌp/', 'A2', 'phrasal verb', 'Nhấc một vật gì đó lên khỏi mặt đất hoặc bề mặt.', 'to lift something from the ground or a surface using your hand.', 'Could you please pick up the dropped pen for me?', 'Bạn có thể nhặt giúp tôi chiếc bút bị rơi không?', '{\"en\": \"Could you pick up the printed contracts from the reception desk before the meeting?\", \"vi\": \"Bạn có thể lấy các hợp đồng đã in từ bàn lễ tân trước cuộc họp không?\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pick-up-ljspeech-60ee3a8f.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pick-up-cori-60ee3a8f.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/pick-up-19b623ee.webp', '[\"collect\", \"retrieve\", \"gather\"]', '[\"put down\", \"drop\"]', '[{\"phrase\": \"pick up an order\", \"meaning\": \"lấy đơn hàng\"}, {\"phrase\": \"pick up the phone\", \"meaning\": \"nhấc máy điện thoại\"}, {\"phrase\": \"pick up a package\", \"meaning\": \"lấy bưu kiện\"}]', '[{\"word\": \"pick out\", \"note_vi\": \"pick out nghĩa là chọn lựa, pick up nghĩa là nhặt lên hoặc đón ai đó\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/pick-up-cori-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-aru0-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-aru5-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-aru6-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-aru10-60ee3a8f.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/pick-up-aru9-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-aru3-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-aru7-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-aru8-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-aru2-60ee3a8f.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/pick-up-ljspeech-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-lt408-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-lt138-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-lt624-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-lt396-60ee3a8f.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/pick-up-lt498-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-lt132-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-lt288-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-lt42-60ee3a8f.mp3\", \"/storage/v1/object/public/pronunciation/v2/pick-up-lt90-60ee3a8f.mp3\"]}}', '\'Pick up\' có nhiều nghĩa: nhặt lên, đón người, nhấc máy, hoặc cải thiện — chú ý ngữ cảnh.', 'office', 1, 0),
('7c08ea45-88ae-581b-a2ce-4fda91c1ff51', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', 'bd06fdb4-aaee-573a-88da-8be75b94f77f', '7d041f49-ed3c-576f-b4fb-1a623a43534d', 'delay', '/dɪˈleɪ/', 'A2', 'verb', 'Trì hoãn, làm chậm trễ.', 'to make something happen at a later time than originally planned or expected.', 'The flight was delayed due to bad weather conditions.', 'Chuyến bay bị hoãn do điều kiện thời tiết xấu.', '{\"en\": \"Technical difficulties will likely delay the launch of our new software product until next month.\", \"vi\": \"Các vấn đề kỹ thuật có khả năng sẽ làm trì hoãn việc ra mắt sản phẩm phần mềm mới đến tháng sau.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/delay-ljspeech-ab464f02.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/delay-cori-ab464f02.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/delay-0928fcd7.webp', '[\"postpone\", \"defer\"]', '[\"expedite\", \"accelerate\"]', '[{\"phrase\": \"delay a project\", \"meaning\": \"trì hoãn dự án\"}, {\"phrase\": \"cause a delay\", \"meaning\": \"gây ra sự chậm trễ\"}]', '[{\"word\": \"postpone\", \"note_vi\": \"Postpone thường dùng cho cuộc họp, delay dùng cho tiến độ/lịch trình.\"}]', '[{\"pos\": \"noun\", \"word\": \"delay\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/delay-cori-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-aru0-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-aru5-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-aru6-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-aru10-ab464f02.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/delay-aru9-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-aru3-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-aru7-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-aru8-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-aru2-ab464f02.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/delay-ljspeech-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-lt408-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-lt138-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-lt624-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-lt396-ab464f02.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/delay-lt498-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-lt132-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-lt288-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-lt42-ab464f02.mp3\", \"/storage/v1/object/public/pronunciation/v2/delay-lt90-ab464f02.mp3\"]}}', 'Dùng cả như danh từ và động từ, rất hay gặp trong thông báo sân bay/công việc.', 'business', 1, 1),
('cb0ac1bd-eaa0-52a6-b5cb-eb58b979cf0d', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', 'bd06fdb4-aaee-573a-88da-8be75b94f77f', '7d041f49-ed3c-576f-b4fb-1a623a43534d', 'contact', '/ˈkɒntækt/', 'A2', 'verb', 'liên lạc, tiếp xúc với ai đó', 'to communicate with someone by calling them or sending an email.', 'Clients can contact customer support via email or phone for immediate technical help.', 'Khách hàng có thể liên hệ với bộ phận hỗ trợ khách hàng qua email hoặc điện thoại để được trợ giúp kỹ thuật ngay lập tức.', '{\"en\": \"Please contact our customer service department if you need to change your shipping address.\", \"vi\": \"Vui lòng liên hệ với bộ phận dịch vụ khách hàng nếu bạn cần thay đổi địa chỉ giao hàng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/contact-ljspeech-1a73af9e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/contact-cori-1a73af9e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/contact-44e9a16b.webp', '[\"reach\", \"communicate\", \"touch base\"]', '[\"ignore\", \"avoid\"]', '[{\"phrase\": \"contact directly\", \"meaning\": \"liên hệ trực tiếp\"}, {\"phrase\": \"contact immediately\", \"meaning\": \"liên hệ ngay lập tức\"}, {\"phrase\": \"contact for details\", \"meaning\": \"liên hệ để biết chi tiết\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"contact\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/contact-cori-1a73af9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/contact-aru0-1a73af9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/contact-aru5-1a73af9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/contact-aru6-1a73af9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/contact-aru10-1a73af9e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/contact-aru9-1a73af9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/contact-aru3-1a73af9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/contact-aru7-1a73af9e.mp3\", \"/storage/v1/object/publ