('83608a8b-ff2c-53ca-bac0-fb7abee0695d', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', 'd3b89f70-2a74-5ffa-bf40-783e3bf806a9', '905a7106-fc20-5066-a01f-f183324a3fab', 'counsel', 'UK: /ˈkaʊnsəl/ | US: /ˈkaʊnsəl/', 'B2', 'verb', 'tư vấn, khuyên nhủ', 'to give professional advice, guidance, or instruction to someone facing a specific situation', 'She offers to counsel her colleagues on career development.', 'Cô ấy đề nghị tư vấn cho đồng nghiệp về phát triển sự nghiệp.', '{\"en\": \"Financial advisors counsel clients on how to manage their investments safely.\", \"vi\": \"Các cố vấn tài chính tư vấn cho khách hàng về cách quản lý các khoản đầu tư an toàn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/counsel-ljspeech-e5de0ecc.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/counsel-cori-e5de0ecc.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/counsel-6bada6b3.webp', '[\"advise\", \"guide\", \"instruct\", \"recommend\"]', NULL, '[{\"phrase\": \"counsel clients\", \"meaning\": \"tư vấn cho khách hàng\"}, {\"phrase\": \"counsel someone on\", \"meaning\": \"khuyên bảo/tư vấn cho ai về điều gì\"}]', '[{\"word\": \"council\", \"note_vi\": \"hội đồng, ban quản lý\"}]', '[{\"pos\": \"noun\", \"word\": \"counsel\"}, {\"pos\": \"noun\", \"word\": \"counselor\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/counsel-cori-e5de0ecc.mp3\", \"/storage/v1/object/public/pronunciation/v2/counsel-aru0-e5de0ecc.mp3\", \"/storage/v1/object/public/pronunciation/v2/counsel-aru5-e5de0ecc.mp3\", \"/storage/v1/object/public/pronunciation/v2/counsel-aru6-e5de0ecc.mp3\", \"/storage/v1/object/public/pronunciation/v2/counsel-aru10-e5de0ecc.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/counsel-aru9-e5de0ecc.mp3\", \"/storage/v1/object/public/pronunciation/v2/counsel-aru3-e5de0ecc.mp3\", \"/storage/v1/object/public/pronunciation/v2/counsel-aru7-e5de0ecc.mp3\", \"/storage/v1/object/public/pronunciation/v2/counsel-aru8-