('3e186941-6f36-5604-a963-0089a8de585e', '1e3e6ebb-26a1-52f6-bdc5-1d743722fae2', 'e835ce7b-ff5f-5317-afd9-b4a37b50d589', 'a121933b-7c8f-5070-bb89-a7a5da6023d5', 'due', 'UK: /djuː/ | US: /duː/', 'B1', 'adjective', 'đến hạn, đáo hạn', 'expected or required to happen or be submitted at a designated time.', 'The report is due by Friday afternoon.', 'Báo cáo này đến hạn vào chiều thứ Sáu.', '{\"en\": \"The quarterly financial report is due on Friday afternoon.\", \"vi\": \"Báo cáo tài chính quý đến hạn vào chiều thứ Sáu.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/due-ljspeech-30cdf73e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/due-cori-30cdf73e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/due-b4f4595f.webp', '[\"expected\", \"scheduled\", \"owed\"]', '[\"overdue\"]', '[{\"phrase\": \"be due to\", \"meaning\": \"dự kiến sẽ (làm gì)\"}, {\"phrase\": \"be due on\", \"meaning\": \"đến hạn vào (ngày nào)\"}]', '[{\"word\": \"overdue\", \"note_vi\": \"\'due\' là đến hạn, còn \'overdue\' là đã quá hạn.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/due-cori-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru0-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru5-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru6-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru10-30cdf73e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/due-aru9-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru3-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru7-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru8-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-aru2-30cdf73e.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/due-ljspeech-30cdf73e.mp3\", \"/storage/v1/object/public/pronunciation/v2/due-lt408-30cdf73e.mp3\", \"/storage/v1/object/